namespace UniversityCourseCatalog.Services;

public class CatalogService
{
    private readonly List<Department> _departments;
    private readonly List<Course> _courses;

    public CatalogService()
    {
        _departments = new List<Department>
        {
            new() { Code = "CS", Name = "Computer Science", Description = "Study of computation, algorithms, data structures, and the design of software and hardware systems." },
            new() { Code = "MATH", Name = "Mathematics", Description = "Exploration of abstract structures, quantities, and patterns through rigorous logical reasoning." },
            new() { Code = "ENG", Name = "English", Description = "Analysis of literature, rhetoric, and composition across historical and contemporary contexts." },
            new() { Code = "PHYS", Name = "Physics", Description = "Investigation of matter, energy, and the fundamental forces governing the natural world." },
            new() { Code = "HIST", Name = "History", Description = "Examination of past events, societies, and cultures to understand the forces that shaped the modern world." },
            new() { Code = "BIO", Name = "Biology", Description = "Study of living organisms, their structures, functions, evolution, and interactions with the environment." },
        };

        _courses = new List<Course>
        {
            // Computer Science
            new() { Id = 1, Code = "CS 101", Title = "Introduction to Computer Science", Description = "A broad introduction to computer science covering computational thinking, basic programming in Python, data representation, and an overview of how computers work. No prior experience required.", Credits = 3, Schedule = "Mon/Wed/Fri 9:00–9:50 AM", Location = "Science Hall 201", InstructorName = "Dr. Ada Lovelace", InstructorBio = "Dr. Lovelace holds a Ph.D. in Computer Science from MIT. She specializes in programming language theory and has 15 years of teaching experience.", DepartmentCode = "CS", IsFeatured = true },
            new() { Id = 2, Code = "CS 201", Title = "Data Structures and Algorithms", Description = "In-depth study of fundamental data structures (arrays, linked lists, trees, graphs, hash tables) and algorithm design techniques (divide and conquer, dynamic programming, greedy algorithms). Includes weekly programming assignments in Java.", Credits = 4, Schedule = "Tue/Thu 10:30–11:45 AM", Location = "Science Hall 305", InstructorName = "Dr. Alan Turing", InstructorBio = "Dr. Turing is a renowned researcher in computational theory with over 50 published papers. He joined the faculty after a decade at a leading tech research lab.", DepartmentCode = "CS", IsFeatured = true },
            new() { Id = 3, Code = "CS 310", Title = "Database Systems", Description = "Principles of relational database design, SQL, normalization, indexing, transaction management, and an introduction to NoSQL databases. Students complete a semester-long project building a database-backed application.", Credits = 3, Schedule = "Mon/Wed 1:00–2:15 PM", Location = "Tech Center 110", InstructorName = "Dr. Edgar Codd", InstructorBio = "Dr. Codd brings 20 years of industry experience in data engineering. His research focuses on query optimization and distributed database systems.", DepartmentCode = "CS" },
            new() { Id = 4, Code = "CS 420", Title = "Artificial Intelligence", Description = "Survey of AI techniques including search, knowledge representation, machine learning, neural networks, and natural language processing. Includes hands-on projects using Python and TensorFlow.", Credits = 3, Schedule = "Tue/Thu 2:00–3:15 PM", Location = "Science Hall 401", InstructorName = "Dr. Ada Lovelace", InstructorBio = "Dr. Lovelace holds a Ph.D. in Computer Science from MIT. She specializes in programming language theory and has 15 years of teaching experience.", DepartmentCode = "CS", IsFeatured = true },

            // Mathematics
            new() { Id = 5, Code = "MATH 101", Title = "Calculus I", Description = "Limits, continuity, derivatives, and integrals of single-variable functions. Applications to physics, engineering, and economics. Graphing calculator required.", Credits = 4, Schedule = "Mon/Wed/Fri 10:00–10:50 AM", Location = "Math Building 102", InstructorName = "Dr. Emmy Noether", InstructorBio = "Dr. Noether is an award-winning educator who has taught calculus for 18 years. Her research interests include abstract algebra and topology.", DepartmentCode = "MATH", IsFeatured = true },
            new() { Id = 6, Code = "MATH 201", Title = "Linear Algebra", Description = "Vector spaces, matrices, linear transformations, eigenvalues and eigenvectors, with applications to data science and computer graphics.", Credits = 3, Schedule = "Tue/Thu 9:00–10:15 AM", Location = "Math Building 204", InstructorName = "Dr. Carl Gauss", InstructorBio = "Dr. Gauss specializes in numerical analysis and has authored three widely-used textbooks on linear algebra.", DepartmentCode = "MATH" },
            new() { Id = 7, Code = "MATH 301", Title = "Probability and Statistics", Description = "Probability theory, random variables, distributions, hypothesis testing, confidence intervals, and regression analysis. Uses R for statistical computing.", Credits = 3, Schedule = "Mon/Wed 2:30–3:45 PM", Location = "Math Building 310", InstructorName = "Dr. Emmy Noether", InstructorBio = "Dr. Noether is an award-winning educator who has taught calculus for 18 years. Her research interests include abstract algebra and topology.", DepartmentCode = "MATH" },

            // English
            new() { Id = 8, Code = "ENG 101", Title = "Composition and Rhetoric", Description = "Develops skills in academic writing, argumentation, and critical reading. Students produce multiple essays and a research paper over the semester.", Credits = 3, Schedule = "Mon/Wed/Fri 11:00–11:50 AM", Location = "Humanities Hall 105", InstructorName = "Prof. Virginia Woolf", InstructorBio = "Prof. Woolf is a published author and literary critic with expertise in modernist literature and creative nonfiction.", DepartmentCode = "ENG" },
            new() { Id = 9, Code = "ENG 250", Title = "American Literature", Description = "Survey of American literary works from the colonial period to the present, including fiction, poetry, and drama. Examines themes of identity, democracy, and social change.", Credits = 3, Schedule = "Tue/Thu 1:00–2:15 PM", Location = "Humanities Hall 210", InstructorName = "Prof. Virginia Woolf", InstructorBio = "Prof. Woolf is a published author and literary critic with expertise in modernist literature and creative nonfiction.", DepartmentCode = "ENG" },

            // Physics
            new() { Id = 10, Code = "PHYS 101", Title = "General Physics I", Description = "Mechanics, thermodynamics, and waves. Includes weekly laboratory sessions. Calculus I is a prerequisite or corequisite.", Credits = 4, Schedule = "Mon/Wed/Fri 1:00–1:50 PM + Lab Thu 2:00–4:50 PM", Location = "Physics Lab 101", InstructorName = "Dr. Richard Feynman", InstructorBio = "Dr. Feynman is known for his engaging lecture style and has received multiple teaching excellence awards. His research spans quantum electrodynamics and particle physics.", DepartmentCode = "PHYS", IsFeatured = true },
            new() { Id = 11, Code = "PHYS 201", Title = "General Physics II", Description = "Electricity, magnetism, optics, and modern physics. Continues the laboratory component from Physics I.", Credits = 4, Schedule = "Mon/Wed/Fri 2:00–2:50 PM + Lab Tue 3:00–5:50 PM", Location = "Physics Lab 101", InstructorName = "Dr. Richard Feynman", InstructorBio = "Dr. Feynman is known for his engaging lecture style and has received multiple teaching excellence awards. His research spans quantum electrodynamics and particle physics.", DepartmentCode = "PHYS" },

            // History
            new() { Id = 12, Code = "HIST 101", Title = "World History to 1500", Description = "Survey of major civilizations, empires, and cultural developments from antiquity through the late medieval period. Emphasizes primary source analysis.", Credits = 3, Schedule = "Tue/Thu 11:00 AM–12:15 PM", Location = "Liberal Arts 301", InstructorName = "Prof. Howard Zinn", InstructorBio = "Prof. Zinn is an acclaimed historian whose work focuses on social movements and grassroots history. He has published extensively on modern political history.", DepartmentCode = "HIST" },
            new() { Id = 13, Code = "HIST 202", Title = "Modern European History", Description = "Europe from the Enlightenment through the 21st century, covering revolution, industrialization, world wars, and European integration.", Credits = 3, Schedule = "Mon/Wed 10:00–11:15 AM", Location = "Liberal Arts 305", InstructorName = "Prof. Howard Zinn", InstructorBio = "Prof. Zinn is an acclaimed historian whose work focuses on social movements and grassroots history. He has published extensively on modern political history.", DepartmentCode = "HIST" },

            // Biology
            new() { Id = 14, Code = "BIO 101", Title = "Introduction to Biology", Description = "Foundational concepts in cell biology, genetics, evolution, and ecology. Includes a weekly lab. Designed for both majors and non-majors.", Credits = 4, Schedule = "Mon/Wed/Fri 8:00–8:50 AM + Lab Tue 9:00–11:50 AM", Location = "Life Sciences 120", InstructorName = "Dr. Rosalind Franklin", InstructorBio = "Dr. Franklin is a molecular biologist whose research on DNA structure has been widely recognized. She brings a passion for hands-on laboratory education.", DepartmentCode = "BIO", IsFeatured = true },
            new() { Id = 15, Code = "BIO 301", Title = "Genetics", Description = "Mendelian and molecular genetics, gene expression, regulation, and genomics. Prerequisites: BIO 101 and CHEM 101.", Credits = 3, Schedule = "Tue/Thu 3:30–4:45 PM", Location = "Life Sciences 220", InstructorName = "Dr. Rosalind Franklin", InstructorBio = "Dr. Franklin is a molecular biologist whose research on DNA structure has been widely recognized. She brings a passion for hands-on laboratory education.", DepartmentCode = "BIO" },
        };
    }

    public List<Department> GetAllDepartments() => _departments;

    public Department? GetDepartment(string code) =>
        _departments.FirstOrDefault(d => d.Code.Equals(code, StringComparison.OrdinalIgnoreCase));

    public List<Course> GetAllCourses() => _courses;

    public List<Course> GetFeaturedCourses() =>
        _courses.Where(c => c.IsFeatured).ToList();

    public Course? GetCourse(int id) =>
        _courses.FirstOrDefault(c => c.Id == id);

    public List<Course> GetCoursesByDepartment(string departmentCode) =>
        _courses.Where(c => c.DepartmentCode.Equals(departmentCode, StringComparison.OrdinalIgnoreCase)).ToList();

    public List<Course> SearchCourses(string? searchTerm, string? departmentFilter)
    {
        var query = _courses.AsEnumerable();

        if (!string.IsNullOrWhiteSpace(departmentFilter))
        {
            query = query.Where(c => c.DepartmentCode.Equals(departmentFilter, StringComparison.OrdinalIgnoreCase));
        }

        if (!string.IsNullOrWhiteSpace(searchTerm))
        {
            var term = searchTerm.Trim();
            query = query.Where(c =>
                c.Title.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Code.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Description.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.InstructorName.Contains(term, StringComparison.OrdinalIgnoreCase));
        }

        return query.ToList();
    }
}

