        };
    }

    public List<Department> GetAllDepartments() => _departments;

    public Department? GetDepartment(string code) =>
        _departments.FirstOrDefault(d => d.Code.Equals(code, StringComparison.OrdinalIgnoreCase));

    public List<Course> GetAllCourses() => _courses;

    public List<Course> GetFeaturedCourses() =>
        _courses.Where(c => c.IsFeatured).ToList();

    public Course? GetCourse(int id) =>
        _courses.FirstOrDefault(c => c.Id == id);

    public List<Course> GetCoursesByDepartment(string departmentCode) =>
        _courses.Where(c => c.DepartmentCode.Equals(departmentCode, StringComparison.OrdinalIgnoreCase)).ToList();

    public List<Course> SearchCourses(string? searchTerm, string? departmentFilter)
    {
        var query = _courses.AsEnumerable();

        if (!string.IsNullOrWhiteSpace(departmentFilter))
        {
            query = query.Where(c => c.DepartmentCode.Equals(departmentFilter, StringComparison.OrdinalIgnoreCase));
        }

        if (!string.IsNullOrWhiteSpace(searchTerm))
        {
            var term = searchTerm.Trim();
            query = query.Where(c =>
                c.Title.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Code.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Description.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.InstructorName.Contains(term, StringComparison.OrdinalIgnoreCase));
        }

        return query.ToList();
    }
}

