@page "/courses"
@using UniversityCourseCatalog.Services

<PageTitle>Browse Courses — University Course Catalog</PageTitle>

@inject CatalogService Catalog

<h1>Browse Courses</h1>

<form method="get" action="courses" class="row g-3 mb-4">
    <div class="col-md-6">
        <label for="search" class="form-label">Search</label>
        <input type="text" class="form-control" id="search" name="search" value="@Search"
               placeholder="Search by title, code, description, or instructor..." />
    </div>
    <div class="col-md-4">
        <label for="department" class="form-label">Department</label>
        <select class="form-select" id="department" name="department">
            <option value="">All Departments</option>
            @foreach (var dept in Catalog.GetAllDepartments())
            {
                <option value="@dept.Code" selected="@(dept.Code == Department)">@dept.Name</option>
            }
        </select>
    </div>
    <div class="col-md-2 d-flex align-items-end">
        <button type="submit" class="btn btn-primary w-100">Filter</button>
    </div>
</form>

@{
    var results = Catalog.SearchCourses(Search, Department);
}

<p class="text-muted">Showing @results.Count course(s)</p>

@if (results.Count == 0)
{
    <div class="alert alert-info">No courses found matching your criteria. Try adjusting your search or filter.</div>
}
else
{
    <div class="table-responsive">
        <table class="table table-striped table-hover">
            <thead class="table-dark">
                <tr>
                    <th>Code</th>
                    <th>Title</th>
                    <th>Department</th>
                    <th>Credits</th>
                    <th>Instructor</th>
                    <th>Schedule</th>
                    <th></th>
                </tr>
            </thead>
            <tbody>
                @foreach (var course in results)
                {
                    <tr>
                        <td>@course.Code</td>
                        <td><a href="courses/@course.Id">@course.Title</a></td>
                        <td>@course.DepartmentCode</td>
                        <td>@course.Credits</td>
                        <td>@course.InstructorName</td>
                        <td>@course.Schedule</td>
                        <td><a href="enroll?courseId=@course.Id" class="btn btn-outline-success btn-sm">Enroll</a></td>
                    </tr>
                }
            </tbody>
        </table>
    </div>
}

@code {
    [SupplyParameterFromQuery]
    public string? Search { get; set; }

    [SupplyParameterFromQuery]
    public string? Department { get; set; }
}

@page "/courses/{Id:int}"
@using UniversityCourseCatalog.Services

<PageTitle>@(course?.Title ?? "Course Not Found") — University Course Catalog</PageTitle>

@inject CatalogService Catalog

@{
    course = Catalog.GetCourse(Id);
}

@if (course is null)
{
    <h1>Course Not Found</h1>
    <p>The requested course could not be found.</p>
    <a href="courses" class="btn btn-primary">Back to Courses</a>
}
else
{
    var department = Catalog.GetDepartment(course.DepartmentCode);

    <nav aria-label="breadcrumb">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="courses">Courses</a></li>
            @if (department is not null)
            {
                <li class="breadcrumb-item"><a href="courses?department=@department.Code">@department.Name</a></li>
            }
            <li class="breadcrumb-item active" aria-current="page">@course.Code</li>
        </ol>
    </nav>

    <div class="row">
        <div class="col-lg-8">
            <h1>@course.Code — @course.Title</h1>
            @if (course.IsFeatured)
            {
                <span class="badge bg-primary mb-3">Featured Course</span>
            }

            <h2 class="h5 mt-4">Description</h2>
            <p>@course.Description</p>

            <h2 class="h5 mt-4">About the Instructor</h2>
            <p><strong>@course.InstructorName</strong></p>
            <p>@course.InstructorBio</p>
        </div>

        <div class="col-lg-4">
            <div class="card">
                <div class="card-body">
                    <h5 class="card-title">Course Details</h5>
                    <dl>
                        <dt>Credits</dt>
                        <dd>@course.Credits</dd>

                        <dt>Schedule</dt>
                        <dd>@course.Schedule</dd>

                        <dt>Location</dt>
                        <dd>@course.Location</dd>

                        <dt>Department</dt>
                        <dd>@(department?.Name ?? course.DepartmentCode)</dd>
                    </dl>
                    <a href="enroll?courseId=@course.Id" class="btn btn-success w-100">Enroll in This Course</a>
                </div>
            </div>
        </div>
    </div>
}

