}

@page "/enroll"
@using UniversityCourseCatalog.Models
@using UniversityCourseCatalog.Services

<PageTitle>Enrollment Request — University Course Catalog</PageTitle>

@inject CatalogService Catalog

<h1>Enrollment Request</h1>
<p>Fill out the form below to submit your enrollment request. All fields are required.</p>

@if (submitted)
{
    <div class="alert alert-success">
        <h4 class="alert-heading">Request Submitted!</h4>
        <p>Thank you, <strong>@Model.FullName</strong>. Your enrollment request for
            <strong>@(Catalog.GetCourse(Model.CourseId)?.Title ?? "the selected course")</strong>
            has been received.</p>
        <p>A confirmation will be sent to <strong>@Model.Email</strong>.</p>
        <hr />
        <a href="courses" class="btn btn-primary">Browse More Courses</a>
        <a href="enroll" class="btn btn-outline-secondary ms-2">Submit Another Request</a>
    </div>
}
else
{
    <form method="post" action="enroll" class="needs-validation" novalidate>
        <AntiforgeryToken />

        <div class="row">
            <div class="col-md-6">
                <div class="mb-3">
                    <label for="fullName" class="form-label">Full Name</label>
                    <input type="text" class="form-control" id="fullName" name="Model.FullName"
                           value="@Model.FullName" required maxlength="100" />
                    @if (errors.ContainsKey(nameof(Model.FullName)))
                    {
                        <div class="text-danger small mt-1">@errors[nameof(Model.FullName)]</div>
                    }
                </div>

                <div class="mb-3">
                    <label for="studentId" class="form-label">Student ID</label>
                    <input type="text" class="form-control" id="studentId" name="Model.StudentId"
                           value="@Model.StudentId" required maxlength="20"
                           placeholder="e.g. STU-12345" />
                    @if (errors.ContainsKey(nameof(Model.StudentId)))
                    {
                        <div class="text-danger small mt-1">@errors[nameof(Model.StudentId)]</div>
                    }
                </div>

                <div class="mb-3">
                    <label for="email" class="form-label">Email Address</label>
                    <input type="email" class="form-control" id="email" name="Model.Email"
                           value="@Model.Email" required
                           placeholder="you@university.edu" />
                    @if (errors.ContainsKey(nameof(Model.Email)))
                    {
                        <div class="text-danger small mt-1">@errors[nameof(Model.Email)]</div>
                    }
                </div>

                <div class="mb-3">
                    <label for="courseId" class="form-label">Course</label>
                    <select class="form-select" id="courseId" name="Model.CourseId" required>
                        <option value="0">— Select a course —</option>
                        @foreach (var course in Catalog.GetAllCourses())
                        {
                            <option value="@course.Id" selected="@(course.Id == Model.CourseId)">
                                @course.Code — @course.Title (@course.Credits cr.)
                            </option>
                        }
                    </select>
                    @if (errors.ContainsKey(nameof(Model.CourseId)))
                    {
                        <div class="text-danger small mt-1">@errors[nameof(Model.CourseId)]</div>
                    }
                </div>

                <button type="submit" class="btn btn-success">Submit Enrollment Request</button>
                <a href="courses" class="btn btn-outline-secondary ms-2">Cancel</a>
            </div>
        </div>
    </form>
}

@code {
    [SupplyParameterFromForm]
    public EnrollmentRequest Model { get; set; } = new();

    [SupplyParameterFromQuery]
    public int? CourseId { get; set; }

    private bool submitted;
    private Dictionary<string, string> errors = new();

    protected override void OnInitialized()
    {
        if (CourseId.HasValue && Model.CourseId == 0)
        {
            Model.CourseId = CourseId.Value;
        }
    }

    protected override void OnParametersSet()
    {
        if (HttpMethods.IsPost(HttpContextAccessor?.HttpContext?.Request.Method ?? ""))
        {
            HandleSubmit();
        }
    }

    [CascadingParameter]
    public HttpContext? HttpContextAccessor { get; set; }

    private void HandleSubmit()
    {
        errors.Clear();
        var validationResults = new List<System.ComponentModel.DataAnnotations.ValidationResult>();
        var context = new System.ComponentModel.DataAnnotations.ValidationContext(Model);
        if (System.ComponentModel.DataAnnotations.Validator.TryValidateObject(Model, context, validationResults, true))
        {
            submitted = true;
        }
        else
        {
            foreach (var result in validationResults)
            {
                foreach (var member in result.MemberNames)
                {
                    if (!errors.ContainsKey(member))
                    {
                        errors[member] = result.ErrorMessage ?? "Invalid value.";
                    }
                }
            }
        }
    }
}

